  "code_excerpt": "// core/state/statedb.go:790-970 — IntermediateRoot (Go equivalent of _prepare_trie)
func (s *StateDB) IntermediateRoot(deleteEmptyObjects bool) common.Hash {
	s.Finalise(deleteEmptyObjects)
	// ... initializes trie, prefetcher ...
	for addr, op := range s.mutations {
		if op.applied || op.isDelete() { continue }
		obj := s.stateObjects[addr]
		workers.Go(func() error {
			if s.db.TrieDB().IsVerkle() {
				obj.updateTrie()
			} else {
				obj.updateRoot()  // <-- computes storage trie root, stores in obj.data.Root
			}
			return nil
		})
	}
	// ... after workers done ...
	for addr, op := range s.mutations {
		if op.applied { continue }
		op.applied = true
		if op.isDelete() {
			deletedAddrs = append(deletedAddrs, addr)
		} else {
			s.updateStateObject(s.stateObjects[addr])  // <-- inserts account into account trie
		}
	}
	hash := s.trie.Hash()
	return hash
}

// core/state/statedb.go:570-578 — updateStateObject
func (s *StateDB) updateStateObject(obj *stateObject) {
	if err := s.trie.UpdateAccount(obj.Address(), &obj.data, len(obj.code)); err != nil {
		s.setError(fmt.Errorf("updateStateObject (%x) error: %v", obj.Address(), err))
	}
}

// trie/secure_trie.go:214-227 — UpdateAccount
func (t *StateTrie) UpdateAccount(address common.Address, acc *types.StateAccount, _ int) error {
	hk := crypto.Keccak256(address.Bytes())
	data, err := rlp.EncodeToBytes(acc)  // <-- RLP-encodes {Nonce, Balance, Root, CodeHash}
	if err != nil { return err }
	if err := t.trie.Update(hk, data); err != nil { return err }
	if t.preimages != nil {
		t.secKeyCache[common.Hash(hk)] = address.Bytes()
	}
	return nil
}

// core/types/state_account.go:31-36 — StateAccount struct
type StateAccount struct {
	Nonce    uint64
	Balance  *uint256.Int
	Root     common.Hash // merkle root of the storage trie  <-- ALWAYS present
	CodeHash []byte
}

// core/state/state_object.go:367-375 — updateRoot (computes storage root)
func (s *stateObject) updateRoot() {
	tr, err := s.updateTrie()
	if err != nil || tr == nil { return }
	s.data.Root = tr.Hash()  // <-- storage root is computed and stored
}

// core/state/state_object.go:424-452 — commit (commits storage changes)
func (s *stateObject) commit() (*accountUpdate, *trienode.NodeSet, error) {
	op := &accountUpdate{
		address: s.address,
		data:    types.SlimAccountRLP(s.data),  // <-- includes Root
	}
	s.commitStorage(op)
	root, nodes := s.trie.Commit(false)
	s.data.Root = root  // <-- updates Root to committed storage trie root
	return op, nodes, nil
}"
}

